```cpp
#include <iostream>
#include <fstream>
#include <Windows.h>
#include <string>

using namespace std;

int main() {
    // Input file and output directory
    string inputFile, outputDirectory;

    // Prompt user for input
    cout << "Enter input file: ";
    getline(cin, inputFile);
    cout << "Enter output directory: ";
    getline(cin, outputDirectory);

    // Check if user has admin privileges
    if (GetCurrentUser() == L"SYSTEM") {
        cout << "Error: You need to run the application as an administrator." << endl;
        return 1;
    }

    // Open input file
    ifstream inputFile(inputFile, ios_base::in);

    // Check if file exists
    if (!inputFile.is_open()) {
        cout << "Error: Input file does not exist." << endl;
        return 1;
    }

    // Open output directory
    ofstream outputFile(outputDirectory, ios_base::out);

    // Check if directory exists
    if (!outputFile.is_open()) {
        cout << "Error: Output directory does not exist." << endl;
        return 1;
    }

    // Start copying file
    cout << "Copying file..." << endl;

    // Copy file
    char buffer[1024];
    while (inputFile.read(buffer, 1024)) {
        outputFile.write(buffer, 1024);
    }
    outputFile.close();

    cout << "File copied successfully." << endl;

    return 0;
}
```

